```python
def triangle_type(a, b, c):
    # Check for non-positive sides
    if a <= 0 or b <= 0 or c <= 0:
        return "invalid"
    # Check triangle inequality (strict)
    if a + b <= c or a + c <= b or b + c <= a:
        return "invalid"
    # Determine type
    if a == b == c:
        return "equilateral"
    if a == b or a == c or b == c:
        return "isosceles"
    return "scalene"
```

